import 'package:flutter/material.dart';
void main()=>runApp(const MaterialApp(home:ResultApp()));
class ResultApp extends StatefulWidget{const ResultApp({super.key});@override State<ResultApp> createState()=>_ResultAppState();}
class _ResultAppState extends State<ResultApp>{final name=TextEditingController();final marks=List.generate(3,(_)=>TextEditingController());String result='';@override void dispose(){name.dispose();for(final x in marks){x.dispose();}super.dispose();}void calculate(){final v=marks.map((x)=>double.tryParse(x.text)).toList();setState((){if(name.text.trim().isEmpty||v.any((x)=>x==null||x<0||x>100)){result='Enter a name and marks from 0 to 100';return;}final total=v.fold<double>(0,(s,x)=>s+x!);final percentage=total/3;final pass=v.every((x)=>x!>=33);result='Student: ${name.text}\\nTotal: $total / 300\\nPercentage: ${percentage.toStringAsFixed(2)}%\\nResult: ${pass?'Pass':'Fail'}';});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Student Result')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Student name')),for(int i=0;i<3;i++)TextField(controller:marks[i],keyboardType:TextInputType.number,decoration:InputDecoration(labelText:'Subject ${i+1} marks (out of 100)')),ElevatedButton(onPressed:calculate,child:const Text('Calculate result')),Text(result)]));}
